 if(m.type==='gameStatus'){state.running=m.running||[];state.runningVersions=m.runningVersions||{};state.bedrockRunning=m.bedrockRunning===true;if(m.playtime)state.playtime=m.playtime;if(typeof SpectraWorkspace!=='undefined')SpectraWorkspace.refreshPlaytime();settleGameStatus();syncPlayButtons();return;}
 if(m.type==='progress'){transferActive=true;if(sourceUpdateRunning){$('#updateDetail').textContent=(m.message||'Подготовка')+(m.downloadedBytes!=null?' · '+bytes(m.downloadedBytes)+' / '+(m.totalBytes>0?bytes(m.totalBytes)+' · осталось '+bytes(Math.max(0,m.totalBytes-m.downloadedBytes)):'размер неизвестен'):'');$('#updateTrack').classList.toggle('indeterminate',!(m.percent>0));$('#updateBar').style.width=Math.max(0,Math.min(100,m.percent||0))+'%';}$('#status').textContent='Загрузка';$('#progressText').textContent=(m.message||'Подготовка')+(m.downloadedBytes!=null?' · '+bytes(m.downloadedBytes)+' / '+(m.totalBytes>0?bytes(m.totalBytes):'размер неизвестен')+(m.scope==='file'?' · текущий файл':' · текущий этап'):'');$('#progressTrack').classList.toggle('indeterminate',m.indeterminate===true||(m.downloadedBytes!=null&&!(m.totalBytes>0)));$('#progressBar').style.width=Math.max(0,Math.min(100,m.percent||0))+'%';return;}
 if(m.type==='logBatch'){for(const item of m.items||[])onMessage(item);return;}
 if(m.type==='log'){const a=logs.get(m.instanceId)||[];a.push(m.line);if(a.length>5000)a.splice(0,a.length-5000);logs.set(m.instanceId,a);if(editorId===m.instanceId&&editorTab==='logs')scheduleLogPaint(m.instanceId);return;}
