 modal(`${closeButton()}<h2>${existing?'Редактировать сборку':'Новая сборка'}</h2><p>Соберите своё пространство для игры.</p><form id="instanceForm"><div class="form-grid"><label class="wide">Название<input id="instanceName" value="${esc(i.name)}" placeholder="Например, Тихая долина" maxlength="80" required></label><div class="wide toolbar"><label><input type="checkbox" id="createSnapshots"> Снапшоты</label><label><input type="checkbox" id="createBeta"> Бета</label><label><input type="checkbox" id="createAlpha"> Альфа</label></div><label>Minecraft<select id="mcVersion" required><option>Загрузка…</option></select></label><label>Загрузчик<select id="loader">${['vanilla','fabric','forge','quilt','neoforge'].map(l=>`<option value="${l}" ${i.loader===l?'selected':''}>${l==='vanilla'?'Vanilla':l}</option>`).join('')}</select></label><label class="wide">Версия загрузчика<select id="loaderVersion"><option value="">Не требуется</option></select><span id="loaderHint" class="muted"></span></label><div class="wide artwork-picker"><button type="button" id="pickIcon">▧ Выбрать иконку</button><button type="button" id="pickBanner">▧ Выбрать баннер</button></div><div class="wide" id="artPreview">${i.banner?image(i.banner,'artwork-preview'):''}</div></div><div class="form-actions"><button type="button" id="cancel">Отмена</button><button class="primary" id="saveInstance" type="submit">Сохранить сборку</button></div></form>`);
