 $('#main').innerHTML=`<section><div class="editor-head"><button id="back">←</button><div class="instance-icon">${image(i.icon)||pixelIcon('cube')}</div><div class="instance-meta"><div class="eyebrow">РЕДАКТОР СБОРКИ</div><h1 data-no-i18n>${esc(i.name)}</h1><p class="muted">${esc(i.version)} · ${esc(i.loader)} ${esc(i.loaderVersion)}</p></div><button id="editIdentity">Оформление</button><button class="icon-button" data-multi="${esc(i.id)}" title="Запустить несколько клиентов">${pixelIcon('cube')}</button><button class="primary" id="editorPlay">${state.running.includes(i.id)?'■ Остановить':busy.has(i.id)?'Подготовка…':'▷ Играть'}</button></div><div class="editor-layout"><div id="editorContent"></div><aside class="editor-tabs">${tabs.map(([id,t])=>`<button data-tab="${id}" class="${editorTab===id?'active':''}">${t}</button>`).join('')}</aside></div></section>`;
