function readSettings(){return{javaPath:$('#javaPath').value.trim(),minRam:Number($('#minRam').value),maxRam:Number($('#maxRam').value),width:Number($('#gameWidth').value),height:Number($('#gameHeight').value),gpu:$('#gpu').value,hideOnLaunch:$('#hideOnLaunch').checked};}
let settingsDraft=null;
function hasSettingsChanges(){return !!settingsDraft&&settingsDraft.form.isConnected&&JSON.stringify(readSettings())!==settingsDraft.snapshot;}
async function saveSettingsDraft(){
 const draft=settingsDraft;if(!draft||!draft.form.isConnected)return false;
 if(draft.global&&typeof SpectraRedesign!=='undefined')document.querySelector('#settings-tab-game')?.click();if(!draft.form.reportValidity())return false;
 const settings=readSettings();if(settings.maxRam<settings.minRam)throw new Error('Максимум памяти должен быть не меньше минимума');
 if(draft.saving)return false;draft.saving=true;
 try{updateState(await api(draft.global?'settings':'saveInstance',draft.global?{defaults:settings}:{...draft.instance,settings}));draft.snapshot=JSON.stringify(settings);toast('Настройки сохранены');return true;}finally{draft.saving=false;}
}
function leaveSettings(){
 if(!hasSettingsChanges()){settingsDraft=null;return Promise.resolve(true);}
 if(settingsDraft.pending)return settingsDraft.pending;
 const draft=settingsDraft;
 draft.pending=new Promise(resolve=>{
  modal('<h2>У вас есть несохранённые настройки</h2><p>Сохраните изменения перед выходом из меню настроек.</p><div class="form-actions"><button id="settingsStay">Отмена</button><button id="settingsSaveAndLeave" class="primary">Сохранить</button></div>');
  const dialog=$('#modal');let saved=false;
  dialog.addEventListener('close',()=>{draft.pending=null;if(saved)settingsDraft=null;resolve(saved);},{once:true});
  $('#settingsStay').onclick=()=>dialog.close();
  $('#settingsSaveAndLeave').onclick=()=>run(async()=>{const button=$('#settingsSaveAndLeave');button.disabled=true;try{if(await saveSettingsDraft()){saved=true;dialog.close();}}finally{if(button.isConnected)button.disabled=false;}});
 });return draft.pending;
}
function bindSettings(global,i){
 settingsDraft={form:$('#settingsForm'),global,instance:i,snapshot:JSON.stringify(readSettings()),saving:false,pending:null};
 $('#chooseJava').onclick=()=>run(async()=>{const path=await api('pickJava');if(path)$('#javaPath').value=path;});
 run(async()=>{const gpus=await api('gpus');if($('#gpuNames'))$('#gpuNames').textContent=gpus.join(' / ')||'Не удалось определить';});
 $('#settingsForm').onsubmit=e=>{e.preventDefault();run(()=>saveSettingsDraft());};
}
function renderSettings(){$('#main').innerHTML=`<section>${heading('ПОД ТВОИ ПРИВЫЧКИ','Настройки')}<p class="muted">Эти параметры применяются к новым сборкам.</p>${settingsForm(state.defaults,true)}<div class="panel settings-section"><h2>Аккаунт Minecraft</h2><p>Ник, скин и доступные плащи изменяются в профиле.</p><button data-page="profile">Открыть профиль →</button></div></section>`;bindSettings(true);if(typeof SpectraContent!=='undefined')SpectraContent.settings($('#main'));window.SpectraFriends?.settings($('#main'));$('#main').insertAdjacentHTML('beforeend',`<div class="panel settings-section"><h2>Windows и фоновая работа</h2><label><input id="startupWindows" type="checkbox" ${state.startWithWindows?'checked':''}> Запускать Spectra вместе с Windows в фоновом режиме</label><p class="muted">Окно не открывается. Лаунчер доступен через значок в трее.</p></div>`);$('#startupWindows').onchange=()=>run(async()=>{const checkbox=$('#startupWindows'),wanted=checkbox.checked;checkbox.disabled=true;try{updateState(await api('startupWindows',{enabled:wanted}));}catch(error){checkbox.checked=!wanted;throw error;}finally{checkbox.disabled=false;}});if(typeof SpectraWorkspace!=='undefined')SpectraWorkspace.settings($('#main'));bind($('#main'));SpectraAppearance.mount($('#main'));if(typeof SpectraRedesign!=='undefined')SpectraRedesign.settings();}
function configurationModal(){modal(`${closeButton()}<h2>Вход Microsoft</h2><p>Нажмите «Войти с Microsoft». По умолчанию официальная страница Microsoft откроется во встроенном окне: выберите аккаунт и подтвердите доступ. Если разработчик настроил собственную регистрацию Spectra, вход откроется в браузере по умолчанию. Затем лаунчер подключит профиль Minecraft Java Edition.</p><div class="warning">Для встроенного провайдера CmlLib свой Client ID не требуется. Доступность входа зависит от Microsoft и Minecraft Services. Для игры нужен аккаунт с Minecraft Java Edition.</div><div class="form-actions"><button class="primary" id="modalLogin">Войти с Microsoft ${pixelIcon('arrow')}</button></div>`);$('#modalLogin').onclick=()=>run(async()=>{$('#modal').close();await login();});}

let profileRequest=0;
function skinUrl(p){return (p?.skins?.find(x=>x.state==='ACTIVE')?.url||p?.skins?.[0]?.url||'').replace(/^http:\/\/textures\.minecraft\.net\//,'https://textures.minecraft.net/');}
let displayedProfile=null;
function capeUrl(p){return (p?.capes?.find(c=>c.state==='ACTIVE')?.url||'').replace(/^http:\/\/textures\.minecraft\.net\//,'https://textures.minecraft.net/');}
function renderProfile(player=state.profile){
 displayedProfile=player;
 const request=++profileRequest,p=player,own=!!p&&p.id===state.profile?.id;
 $('#main').innerHTML=`<section>${heading('MINECRAFT JAVA EDITION','Профиль')}<div class="hero profile-hero"><div class="profile-avatar">${esc((p?.name||'S')[0])}</div><div class="profile-copy"><div class="eyebrow">${own?'МОЙ ПРОФИЛЬ':'ПРОФИЛЬ ИГРОКА'}</div><div class="profile-name-line"><h1 data-no-i18n>${esc(p?.name||'Гость')}</h1>${own?`<button id="editProfileName" class="icon-button" aria-label="Изменить ник">${pixelIcon('edit')}</button>`:''}</div>${own?`<form id="profileNameForm" hidden><input id="newName" aria-label="Новый ник" value="${esc(p.name)}" minlength="3" maxlength="16" required pattern="[A-Za-z0-9_]{3,16}"><div id="nameConfirm" hidden><p>Вы точно хотите изменить свой ник Minecraft?</p><div class="name-confirm-actions"><button id="nameNo" type="button">Нет</button><button id="nameYes" type="button" class="primary">Да</button></div></div></form>`:''}<span id="networkVerifiedBadge" class="pill" hidden>ВЕРИФИЦИРОВАН</span><p>${p?'Minecraft Java Edition':'Войдите, чтобы изменить скин и играть.'}</p><span class="pill">${own?'АККАУНТ ПОДКЛЮЧЁН':'ПРОСМОТР'}</span></div>${!p?'<button id="profileLogin" class="primary">Войти с Microsoft</button>':''}</div>
 <div class="toolbar"><input id="playerSearch" placeholder="Ник игрока" value="${esc(p?.name||'')}"><button id="findPlayer">Найти игрока</button>${state.profile&&!own?'<button id="myProfile">Мой профиль</button><button id="profileFriendRequest">Добавить в друзья</button><span id="profileOnline" class="muted"></span>':''}<button id="craftyLink">Crafty ↗</button></div>
 <div class="profile-grid"><div class="panel"><h2>3D-превью скина</h2><div id="skinPreview" class="skin-stage"></div><p class="muted">Перетаскивайте мышью, чтобы повернуть модель.</p></div><div class="panel"><h2>Информация игрока</h2><dl class="player-info"><dt>UUID</dt><dd>${esc(p?.id||'Нет аккаунта')}</dd><dt>Ссылка на профиль</dt><dd>${esc(p?.name?'crafty.gg/@'+p.name:'Нет данных')}</dd><dt>Модель</dt><dd>${esc(p?.skins?.[0]?.variant||'Нет данных')}</dd><dt>Дата создания Minecraft-аккаунта</dt><dd>Не предоставлена источником</dd></dl><div id="craftyData"><p class="muted">Получаем дополнительные сведения…</p></div></div></div>
 ${own?`<div id="networkAccountSettings" class="panel profile-edit"></div><div id="minecraftAppearance" class="panel profile-edit"><div class="toolbar"><button id="changeSkin">Загрузить и надеть PNG</button></div><div class="cape-list">${(p.capes||[]).map(c=>`<button class="cape-tile ${c.state==='ACTIVE'?'equipped':''}" data-cape="${esc(c.id)}" aria-pressed="${c.state==='ACTIVE'}"><div class="cape-preview" data-cape-preview="${esc(c.id)}"></div><span data-no-i18n>${esc(c.alias||c.id)}</span>${c.state==='ACTIVE'?'<small>Надет</small>':''}</button>`).join('')||'<p>Доступных плащей нет</p>'}<button id="hideCape">Скрыть плащ</button></div></div><div class="panel profile-edit"><div class="section-label"><h2>Мои сохранённые скины</h2><label class="skin-model-select">Модель<select id="skinVariant"><option value="classic">Обычные руки</option><option value="slim">Тонкие руки</option></select></label><button id="addSkin">${pixelIcon('plus')} Добавить PNG</button></div><p class="muted">Видны только в вашем профиле этого лаунчера. Добавление не меняет скин в игре.</p><div class="saved-skins">${(state.skins||[]).map(x=>`<article class="saved-skin"><div class="saved-pair" data-face="${esc(x.id)}"></div><h3 data-no-i18n>${esc(x.name)}</h3><p class="muted">${date(x.added)} · ${esc(x.variant)}</p><button data-preview-skin="${esc(x.id)}">Превью</button><button data-apply-skin="${esc(x.id)}">Надеть</button><button data-remove-skin="${esc(x.id)}">Удалить из списка</button></article>`).join('')||'<p>Список пока пуст.</p>'}</div></div>`:''}
 <div id="histories" class="profile-grid"><div class="panel"><h2>История ников</h2><div id="nameHistory">Нет данных</div></div><div class="panel"><h2>История скинов Crafty</h2><div id="skinHistory">Нет данных</div></div></div></section>`;
 window.SpectraFriends?.profile(p,own);
 $('#profileLogin')?.addEventListener('click',()=>run(()=>login()));
 if(p){paintFace($('.profile-avatar'),skinUrl(p));mountSkin($('#skinPreview'),skinUrl(p),p.skins?.[0]?.variant,capeUrl(p));}
 $('#myProfile')?.addEventListener('click',()=>renderProfile());
 $('#findPlayer').onclick=()=>run(async()=>{const name=$('#playerSearch').value.trim();const found=await api('player',{name});if(request===profileRequest&&page==='profile')renderProfile(found);});
 $('#craftyLink').onclick=()=>run(()=>api('external',{url:'https://crafty.gg/players/'+encodeURIComponent($('#playerSearch').value.trim())}));
 if(own){for(const cape of p.capes||[])paintCape($(`[data-cape-preview="${cape.id}"]`),(cape.url||'').replace('http://textures.minecraft.net/','https://textures.minecraft.net/'));$('#changeSkin').onclick=()=>profileAction('skin',{variant:$('#skinVariant').value});$('#hideCape').onclick=()=>profileAction('hideCape');$$('[data-cape]').forEach(b=>b.onclick=()=>profileAction('cape',{capeId:b.dataset.cape}));$('#addSkin').onclick=()=>run(async()=>{updateState(await api('addSkin',{variant:$('#skinVariant').value}));renderProfile();});for(const x of state.skins||[]){paintSkinPair($(`[data-face="${x.id}"]`),x.image,x.variant);$(`[data-preview-skin="${x.id}"]`).onclick=()=>mountSkin($('#skinPreview'),x.image,x.variant,capeUrl(p));$(`[data-apply-skin="${x.id}"]`).onclick=()=>run(async()=>{updateState(await api('applySkin',{id:x.id}));renderProfile();toast('Скин изменён в Minecraft');});$(`[data-remove-skin="${x.id}"]`).onclick=()=>run(async()=>{updateState(await api('removeSkin',{id:x.id}));renderProfile();});}}
 if(typeof SpectraWorkspace!=='undefined')SpectraWorkspace.profile(p,own);if(typeof SpectraRedesign!=='undefined')SpectraRedesign.profile(p,own);
 if(p&&!state.offline)api('crafty',{name:p.name}).then(data=>{if(request===profileRequest&&page==='profile')renderCrafty(data);}).catch(e=>{if(request===profileRequest&&$('#craftyData'))$('#craftyData').textContent=e.message;});else $('#craftyData').textContent='Войдите или найдите игрока';
}
function renderCrafty(data){
 const p=data.data?.player||data.data||data.player||data;
 const names=p.username_history||p.usernameHistory||p.usernames||p.name_history||[],skins=p.skin_history||p.skinHistory||p.skins||[];
 const historyDate=x=>x?date(x):'Дата неизвестна';
 $('#craftyData').innerHTML=`<dl class="player-info"><dt>Профиль Crafty создан</dt><dd>${p.created_at||p.createdAt?historyDate(p.created_at||p.createdAt):'Нет данных'}</dd><dt>Статус Crafty</dt><dd>${esc(p.status|| (p.claimed===true?'Подтверждён':p.claimed===false?'Не подтверждён':'Нет данных'))}</dd><dt>Locator Bar</dt><dd>${esc(p.locator_bar?.color||p.locatorBar?.color||'Источник не предоставил цвет')}</dd></dl><p class="muted">Дата профиля Crafty не является датой создания Minecraft-аккаунта.</p>`;
 $('#nameHistory').innerHTML=Array.isArray(names)&&names.length?names.map(x=>`<div class="history-row"><strong data-no-i18n>${esc(typeof x==='string'?x:x.username||x.name)}</strong><span>${historyDate(x.changed_at||x.changedAt||x.created_at)}</span></div>`).join(''):'Источник не предоставил историю ников.';
 const history=Array.isArray(skins)?skins:[];$('#nameHistory').parentElement.hidden=!(Array.isArray(names)&&names.length);$('#skinHistory').parentElement.hidden=!history.length;
 $('#skinHistory').innerHTML=history.length?`<div class="saved-skins">${history.map((x,index)=>`<article class="saved-skin"><div class="saved-pair" data-history-skin="${index}"></div><p class="muted">${historyDate(x.created_at||x.last_seen)}</p><button data-history-preview="${index}">3D-превью</button></article>`).join('')}</div>`:'Источник не предоставил историю скинов.';
 for(const [index,x] of history.entries()){const url=(x.url||x.texture_url||x.skin_url||x.texture?.url||'').replace('http://textures.minecraft.net/','https://textures.minecraft.net/');const variant=x.variant||x.model||'classic';const host=$(`[data-history-skin="${index}"]`);if(url)lazySkinPair(host,url,variant);else host.textContent='Нет адреса текстуры';const button=$(`[data-history-preview="${index}"]`);button.disabled=!safeImage(url);button.onclick=()=>mountSkin($('#skinPreview'),url,variant,capeUrl(displayedProfile));}

}

function profileAction(operation,data={}){return run(async()=>{updateState(await api('profileAction',{operation,...data}));toast('Профиль обновлён');renderProfile();});}
function bytes(n){if(!Number.isFinite(Number(n))||n<0)return SpectraAppearance.language()==='ru'?'0 Б':'0 B';const units=SpectraAppearance.language()==='ru'?['Б','КиБ','МиБ','ГиБ']:['B','KiB','MiB','GiB'];let k=0;while(n>=1024&&k<3){n/=1024;k++;}return n.toLocaleString(SpectraAppearance.language(),{maximumFractionDigits:k?1:0})+' '+units[k];}
function findInstance(id){return id==='vanilla'?{id,name:'Minecraft '+state.selection?.version,version:state.selection?.version,loader:'vanilla',settings:state.defaults}:state.instances.find(x=>x.id===id);}
function viewButtons(kind){return `<select class="view-select" data-view="${kind}" aria-label="Вид списка"><option value="cards">Карточки</option><option value="tiles">Крупные плитки</option><option value="list">Компактный список</option></select>`;}
function bindViews(){$$('[data-view]').forEach(b=>{b.value=state.views?.[b.dataset.view]||'cards';b.onchange=()=>run(async()=>{updateState(await api('view',{kind:b.dataset.view,mode:b.value}));if(page==='versions')renderVersions();else renderInstances();});});}
async function choose(version,instanceId){updateState(await api('select',{version,instanceId}));$$('[data-version]').forEach(b=>b.classList.toggle('selected',!instanceId&&b.dataset.version===version));toast(instanceId?'Сборка выбрана':'Выбрана Minecraft '+version);}
function motionMs(ms){return window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?0:ms;}
let quickCollapsed=false;
try{quickCollapsed=localStorage.getItem('spectra.quickCollapsed')==='true';}catch{}
function quickCard(version,instance,allowBedrock=true){if(allowBedrock&&!instance&&state.selection?.edition==='bedrock')return SpectraBedrock.selectionCard();const name=instance?.name|| (version?'Minecraft '+version:'Выберите версию');const backdrop=instance?.banner||versionArt[instance?.version||version]||instance?.icon;return `<div class="quick-card"><div class="quick-art">${image(backdrop)||'<img src="assets/terrain.svg" alt="">'}</div><div class="quick-shade"></div><div class="quick-caption">${instance?.icon?image(instance.icon,'quick-icon'):pixelIcon('cube')}<div><strong>${esc(name)}</strong><span>${esc(instance?instance.version+' · '+instance.loader:version?'Java Edition':'Версия или модпак')}</span></div></div></div>`;}
let quickSignature='';
function renderQuick(){
 const host=$('#quickLaunch');if(!host)return;host.hidden=state.preferences?.hideQuickLaunch===true;if(host.hidden)return;const selection=state.selection||{},selected=selection.edition==='bedrock'?null:selection.instanceId?findInstance(selection.instanceId):null;
 const signature=JSON.stringify([quickCollapsed,selection,selected?.name,selected?.banner,selected?.icon,versionArt[selected?.version||selection.version]]);if(signature===quickSignature&&$('#quickBody')){syncPlayButtons();return;}quickSignature=signature;$('#quickChoices')?.remove();
 host.classList.toggle('collapsed',quickCollapsed);
 host.innerHTML=`<div class="quick-header"><span class="eyebrow">БЫСТРЫЙ ЗАПУСК</span><button id="quickToggle" aria-expanded="${!quickCollapsed}" aria-controls="quickBody" title="${quickCollapsed?'Развернуть':'Свернуть'}">${quickCollapsed?'＋':'−'}</button></div><div id="quickBody" ${quickCollapsed?'hidden':''}>${quickCard(selection.version,selected)}<button id="quickChoose" aria-expanded="false" aria-controls="quickChoices">Выбрать версию или модпак ▾</button><div id="quickChoices" class="glass" hidden><select id="quickEdition" aria-label="Издание быстрого запуска"><option value="all">Все</option><option value="java">Java Edition</option><option value="bedrock">Bedrock Edition</option><option value="instances">Сборки</option></select><input id="quickSearch" placeholder="Поиск версии или сборки" aria-label="Поиск быстрого запуска"><div id="quickOptions"></div></div><div class="quick-play-actions"><button id="quickMulti" class="icon-button" title="Запустить несколько клиентов" ${selection.edition==='bedrock'?'hidden':''}>${pixelIcon('cube')}</button><button id="quickPlay" class="primary" ${selection.edition==='bedrock'?selection.bedrockId?'':'disabled':selected||selection.version?'':'disabled'}>${pixelIcon('play')} Играть</button></div></div>`;
 $('#quickToggle').onclick=()=>{quickCollapsed=!quickCollapsed;try{localStorage.setItem('spectra.quickCollapsed',String(quickCollapsed));}catch{}quickSignature='';const body=$('#quickBody');if(quickCollapsed){$('#quickChoices').hidden=true;body.animate?.([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(5px)'}],{duration:motionMs(130)}).finished.then(()=>renderQuick()).catch(()=>renderQuick());if(!body.animate)renderQuick();}else{renderQuick();$('#quickBody').animate?.([{opacity:0,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:motionMs(170)});}};
 $('#quickChoose').onclick=()=>{const list=$('#quickChoices');list.hidden=!list.hidden;$('#quickChoose').setAttribute('aria-expanded',String(!list.hidden));if(!list.hidden){document.body.append(list);quickOffset=0;$('#quickEdition').value=state.selection?.edition==='bedrock'?'bedrock':'all';fillQuickOptions();positionQuickChoices();$('#quickSearch').focus();if(typeof SpectraBedrock!=='undefined')SpectraBedrock.load().then(()=>{if($('#quickChoices')&&!$('#quickChoices').hidden)fillQuickOptions();}).catch(e=>toast(e.message));}};
 $('#quickEdition').onchange=()=>{quickOffset=0;fillQuickOptions();};$('#quickSearch').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{quickOffset=0;fillQuickOptions();},120);};
 $('#quickPlay').onclick=()=>state.selection?.edition==='bedrock'?SpectraBedrock.launch():playAction(selected?.id||'vanilla');syncPlayButtons();
}
let quickOffset=0;
function fillQuickOptions(){const query=$('#quickSearch').value.trim().toLowerCase(),edition=$('#quickEdition')?.value||'all';const choices=[...(['all','instances'].includes(edition)?state.instances.filter(i=>(i.name+' '+i.version).toLowerCase().includes(query)).map(i=>({instance:i})):[]),...(['all','java'].includes(edition)?versions.filter(v=>(v.type==='release'||v.id===state.selection?.version||query)&&v.id.toLowerCase().includes(query)).map(v=>({version:v.id})):[]),...(['all','bedrock'].includes(edition)&&typeof SpectraBedrock!=='undefined'?SpectraBedrock.quickOptions(query).map(p=>({bedrock:p})):[])];const list=choices.slice(quickOffset,quickOffset+12);$('#quickOptions').innerHTML=list.map(x=>`<button class="quick-option" ${x.bedrock?`data-quick-bedrock="${esc(x.bedrock.id)}"`:x.instance?`data-quick-instance="${esc(x.instance.id)}"`:`data-quick-version="${esc(x.version)}"`}>${x.bedrock?SpectraBedrock.card(x.bedrock):quickCard(x.version,x.instance,false)}</button>`).join('')||'<p class="muted">Ничего не найдено. Каталог Bedrock загружается при первом открытии.</p>';$('#quickOptions').insertAdjacentHTML('beforeend',`<div class="quick-paging">${quickOffset?'<button id="quickPrev">←</button>':''}${quickOffset+12<choices.length?'<button id="quickNext">Далее →</button>':''}</div>`);$('#quickPrev')?.addEventListener('click',()=>{quickOffset=Math.max(0,quickOffset-12);fillQuickOptions();});$('#quickNext')?.addEventListener('click',()=>{quickOffset+=12;fillQuickOptions();});$$('[data-quick-instance]').forEach(b=>b.onclick=()=>run(()=>choose('',b.dataset.quickInstance)));$$('[data-quick-version]').forEach(b=>b.onclick=()=>run(()=>choose(b.dataset.quickVersion,'')));$$('[data-quick-bedrock]').forEach(b=>b.onclick=()=>run(()=>SpectraBedrock.select(choices.find(x=>x.bedrock?.id===b.dataset.quickBedrock)?.bedrock)));}

function positionQuickChoices(){const popup=$('#quickChoices'),anchor=$('#quickChoose');if(!popup||popup.hidden)return;const r=anchor.getBoundingClientRect(),h=window.innerHeight,w=window.innerWidth;const above=r.top-58,below=h-r.bottom-16,useAbove=above>=below,space=Math.max(80,useAbove?above:below);popup.style.maxHeight=Math.min(390,space)+'px';popup.style.width=Math.min(290,w-24)+'px';popup.style.left=Math.max(12,Math.min(r.left,w-Math.min(290,w-24)-12))+'px';popup.style.top=useAbove?'auto':r.bottom+8+'px';popup.style.bottom=useAbove?h-r.top+8+'px':'auto';}
function playLabel(id){return busy.has(id)?'Подготовка…':state.running.includes(id)?'■ Остановить':pixelIcon('play')+' Играть';}
function syncPlayButtons(){const bedrock=state.selection?.edition==='bedrock';const selected=state.selection?.instanceId||'vanilla';const b=$('#quickPlay');if(b){b.innerHTML=bedrock?state.bedrockRunning?'■ Остановить':busy.has('bedrock')?'Подготовка…':pixelIcon('play')+' '+SpectraBedrock.latestAction():playLabel(selected);b.disabled=bedrock?(!state.bedrockRunning&&(busy.has('bedrock')||!state.selection.bedrockId)):busy.has(selected)||(!state.selection?.instanceId&&!state.selection?.version);b.classList.toggle('launching',busy.has(selected));}$$('.instance-card').forEach(c=>{const button=c.querySelector('[data-launch]');if(button){button.innerHTML=playLabel(c.dataset.id);button.disabled=busy.has(c.dataset.id);button.classList.toggle('launching',busy.has(c.dataset.id));}});$$('[data-bedrock-play]').forEach(button=>{if(state.bedrockRunning){button.dataset.idleLabel ||= button.innerHTML;button.innerHTML='■ Остановить';button.dataset.stopping='true';button.disabled=false;}else if(button.dataset.stopping){button.innerHTML=button.dataset.idleLabel||'Играть';delete button.dataset.stopping;}});$$('[data-play-version]').forEach(button=>{const active=state.running.includes('vanilla')&&state.runningVersions?.vanilla===button.dataset.playVersion;if(active){button.dataset.idleLabel ||= button.innerHTML;button.innerHTML='■ Остановить';button.dataset.stopping='true';button.disabled=false;}else if(button.dataset.stopping){button.innerHTML=button.dataset.idleLabel;delete button.dataset.stopping;}});}
function playAction(id){const button=$('#quickPlay');button?.animate?.([{transform:'translateY(0)'},{transform:'translateY(2px)'},{transform:'translateY(0)'}],{duration:motionMs(150)});if(state.running.includes(id))return run(()=>api('stop',{instanceId:id}));return launch(id);}
window.addEventListener?.('resize',positionQuickChoices);
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#quickLaunch,#quickChoices')&&$('#quickChoices')){$('#quickChoices').hidden=true;$('#quickChoose')?.setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#quickChoices')){$('#quickChoices').hidden=true;$('#quickChoose')?.setAttribute('aria-expanded','false');}});

function exportModal(id){const special=['quilt','neoforge'].includes(findInstance(id).loader);modal(`${closeButton()}<h2>Экспорт Prism / MultiMC</h2><p>ZIP включает моды, настройки и игровые файлы. Java, аккаунты, игровые библиотеки и логи не экспортируются.</p><label class="field">Целевой лаунчер<select id="exportTarget"><option value="prism">Prism Launcher</option><option value="multimc" ${special?'disabled':''}>MultiMC</option></select></label>${special?'<p class="muted">Для этого загрузчика доступен экспорт в Prism.</p>':'<p class="muted">Формат ZIP подходит для Prism и MultiMC.</p>'}<label><input id="exportWorlds" type="checkbox"> Включить миры и скриншоты</label><div class="form-actions"><button id="exportZip" class="primary">Сохранить ZIP</button></div>`);$('#exportZip').onclick=()=>run(async()=>{const b=$('#exportZip');b.disabled=true;try{const result=await api('exportInstance',{instanceId:id,includeWorlds:$('#exportWorlds').checked,target:$('#exportTarget').value});if(!result.cancelled){$('#modal').close();toast('ZIP сохранён для Prism / MultiMC');}}finally{b.disabled=false;}});}
let dragDepth=0;
document.addEventListener('dragenter',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();dragDepth++;document.body.classList.add('pack-drop');}});
document.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;document.body.classList.remove('pack-drop');}});
document.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;document.body.classList.remove('pack-drop');run(async()=>{const files=[...e.dataTransfer.files];if(files.length!==1||!files[0].name.toLowerCase().endsWith('.zip'))throw new Error('Перенесите один ZIP-архив Prism/MultiMC');if(preview)throw new Error('Импорт доступен в Windows-приложении');if(!window.chrome.webview.postMessageWithAdditionalObjects)throw new Error('Обновите Microsoft Edge WebView2 Runtime');const id=String(++seq);const result=await new Promise((resolve,reject)=>{pending.set(id,{resolve,reject});try{window.chrome.webview.postMessageWithAdditionalObjects({id,action:'dropPack',data:{}},files);}catch(error){pending.delete(id);reject(error);}});updateState(result);if($('#shell').hidden){updateState(await api('expand'));openShell();}else navigate('instances');toast('Сборка импортирована');});});
bind();
let sourceUpdateRunning=false;
function showLogin(message='Войдите в Microsoft, чтобы продолжить'){document.body.classList.add('entry-mode');run(()=>api('window',{command:'compact'})); $('#updateScreen').hidden=true;$('#boot').hidden=false;$('#bootStatus').textContent=message; }
let queuedSourceUpdate=null,sourceUpdateOfferTimer=0;
function registerSourceUpdate(b){if(!b?.available||!b.commit)return;const button=$('#footerUpdate');button.hidden=false;button.textContent='Обновить до '+b.version;button.onclick=()=>run(async()=>{if(!await offerSourceUpdate(b.version))return;try{await updateFromCommit(b.commit);}catch(e){openShell();throw e;}});}
function announceSourceUpdate(b){if(!b?.available)return;registerSourceUpdate(b);queuedSourceUpdate=b;clearTimeout(sourceUpdateOfferTimer);presentSourceUpdate();}
function presentSourceUpdate(){if(!queuedSourceUpdate)return;if(sourceUpdateRunning||authActive||$('#shell').hidden||$('#modal').open){sourceUpdateOfferTimer=setTimeout(presentSourceUpdate,1000);return;}const b=queuedSourceUpdate;queuedSourceUpdate=null;run(async()=>{if(await offerSourceUpdate(b.version)){try{await updateFromCommit(b.commit);}catch(e){openShell();throw e;}}});}
function offerSourceUpdate(version){return new Promise(resolve=>{modal(`${closeButton()}<div class="eyebrow">SPECTRA UPDATE</div><h2>Доступно обновление</h2><p><span>Новая версия Spectra</span>: <strong data-no-i18n>${esc(version||'новая версия')}</strong></p><div class="form-actions"><button id="updateAccept" class="primary">Обновить</button></div>`);let accepted=false;$('#updateAccept').onclick=()=>{accepted=true;$('#modal').close();};$('#modal').addEventListener('close',()=>resolve(accepted),{once:true});});}
async function updateFromCommit(commit){if(sourceUpdateRunning)return;sourceUpdateRunning=true;document.body.classList.add('entry-mode');$('#shell').hidden=true;$('#boot').hidden=true;$('#updateScreen').hidden=false;$('#updateTitle').textContent='Обновление';$('#updateDetail').textContent='Подготовка изменённых файлов…';try{return await api('updateSource',{commit});}finally{sourceUpdateRunning=false;}}
async function boot(){try{updateState(await api('state'));if(state.backgroundLaunch){try{registerSourceUpdate(await api('bootstrap'));}catch{}if(state.hasAccount)try{updateState(await api('login',{interactive:false}));}catch{}openShell();return;}if(state.updateReport?.success===false)toast('Обновление не установлено: '+state.updateReport.message);const checkStarted=performance.now();$('#updateTitle').textContent='Проверка коммитов';$('#updateDetail').textContent='Проверяем GitHub…';const b=await api('bootstrap');if(b.commitName){latestCommitLabel={name:b.commitName,sha:b.commit};updateState(state);}$('#updateDetail').textContent=b.update;registerSourceUpdate(b);const firstRun=!preview&&localStorage.getItem(onboardingKey)!=='done';if(firstRun&&b.available)queuedSourceUpdate=b;await new Promise(resolve=>setTimeout(resolve,Math.max(0,900-(performance.now()-checkStarted))));if(!preview&&b.available&&b.automatic!==false&&!firstRun&&await offerSourceUpdate(b.version)){try{await updateFromCommit(b.commit);return;}catch(e){toast('Не удалось установить обновление: '+e.message);}}if(preview){openShell();}else if(firstRun){onboardingPending=true;showWelcome();}else{await api('expand');if(state.hasAccount){$('#updateTitle').textContent='Запуск';$('#updateDetail').textContent='Восстанавливаем аккаунт…';try{await login(false);}catch(e){if(state.profile){openShell();toast('Не удалось обновить вход: '+e.message);}else showLogin('Требуется повторный вход Microsoft: '+e.message);}}else showLogin();}}catch(e){showLogin('Не удалось завершить подготовку');toast(e.message);}}

// Browser preview uses clearly marked sample data. It never pretends to install or authenticate.
async function previewApi(action,data){
 if(action==='preferences'){state.preferences=data;return state;}if(action==='uiScale'){state.interfaceScale=data.scale;return state;}
 if(action==='state'||action==='expand')return state;
 if(action==='bootstrap')return{update:'Просмотр интерфейса · проверка обновлений недоступна',available:false};
 if(action==='versions')return ['1.21.4','1.21.3','1.21.1','1.20.6','1.20.4','1.20.1','1.19.4','1.18.2','1.16.5','1.12.2','1.7.10','1.0','b1.7.3','a1.2.6','25w05a'].map((id,i)=>({id,type:id.startsWith('b')?'old_beta':id.startsWith('a')?'old_alpha':id.includes('w')?'snapshot':'release',releaseTime:new Date(2025-i,0,1).toISOString()}));
 if(action==='loaders')return data.loader==='vanilla'?[]:[{version:'0.16.10',recommended:true},{version:'0.16.9',recommended:false}];
 if(action==='artwork')return {};
 if(action==='components')return [{name:'Minecraft',version:'Просмотр интерфейса'},{name:'Загрузчик',version:'Просмотр интерфейса'}];
 if(action==='gpus')return ['Просмотр интерфейса · GPU не запрошены'];
 if(action==='files')return [];
 if(action==='search')return{items:[],warnings:['Просмотр интерфейса: сетевые каталоги доступны в Windows-приложении.']};
 if(action==='saveInstance'){const i={...data,id:data.id||'preview-'+Date.now()};const old=state.instances.findIndex(x=>x.id===i.id);old<0?state.instances.push(i):state.instances[old]=i;return state;}
 if(action==='contentSources')return [{id:'preview',name:'Просмотр интерфейса',url:'https://www.minecraft.net/'}];
 if(action==='contentSearch')return {items:[],hasMore:false,url:'https://www.minecraft.net/',warning:'Сетевые каталоги доступны в Windows-приложении.'};
 if(action==='bedrockContent')return [];
 if(action==='installedJava')return [];
 if(action==='bedrockVersions')return {installed:[],imported:[],available:[],updates:[],warning:'Проверка Bedrock доступна в Windows-приложении'};
 if(action==='bedrockStore'||action==='bedrockImport'||action==='bedrockLaunch')throw Error('Bedrock доступен в Windows-приложении');
 if(action==='bedrockSelect'){state.selection={edition:'bedrock',bedrockId:data.id,bedrockLabel:data.label};return state;}
 if(action==='projectDetails')throw Error('Каталог доступен в Windows-приложении');
 if(action==='fonts')return [];
 if(action==='importFont')throw Error('Загрузка шрифтов доступна в Windows-приложении');
 if(action==='appearance'){state.appearance=data;return state;}
 if(action==='settings'){state.defaults=data.defaults;return state;}
 if(action==='view'){state.views={...state.views,[data.kind]:data.mode};return state;}
 if(action==='select'){state.selection={edition:'java',version:data.version,instanceId:data.instanceId};return state;}
 if(action==='window')return;
 throw new Error('Это просмотр интерфейса. Действие доступно в приложении Spectra для Windows.');
}
if(preview&&new URLSearchParams(location.search).has('sample'))state.instances=[{id:'sample-1',name:'Тихая долина',version:'1.20.1',loader:'fabric',loaderVersion:'0.16.10',lastPlayed:'2026-10-07',icon:'',banner:'',settings:structuredClone(state.defaults)},{id:'sample-2',name:'Чистый Minecraft',version:'1.21.4',loader:'vanilla',loaderVersion:'',icon:'',banner:'',settings:structuredClone(state.defaults)}];
boot().then(()=>{getVersions().then(()=>renderQuick()).catch(()=>{});api('artwork').then(art=>{versionArt=art;renderQuick();}).catch(()=>{});});
